//! **Lake area before and after the runoff share** (owner choice 2026-11-13, *"Runoff share of rain"*;
//! `DELTA_GEOMETRY_RESEARCH.md` sections 14.6 and 14.10, `LARGE_ITEM_RULINGS.md` Ruling EV's follow-up).
//!
//! Each world is generated by the whole pipeline (`BR_GPU=1` runs the GPU stages, as the app does) twice: with
//! `basin_routing` off (the rules before Ruling EV) and on (the rules since). On each field the lake bodies the map
//! draws are built three ways: the lake water balance with the WHOLE routed discharge as inflow (Ruling ET,
//! `apply_lake_balance(.., 1.0)`), the same with the runoff share (`RUNOFF_SHARE`, what ships), and
//! Ruling CC's area floor after each, as `render::water_bodies_floored_balanced` applies it. Reported: lake cells,
//! lakes (4-connected components), pools, and the target ratio (runoff share after basin routing over whole-rain
//! before it).
//!
//! **Must never** pin a value or change generated output: it only reports. Never un-ignore it: it generates six
//! large worlds.
//!
//! ```text
//! BR_GPU=1 cargo test --release -p cartalith-godot --test lake_runoff_measurement -- --ignored --nocapture --test-threads=1
//! ```
//! `BR_WORLDS=246371,483920,912345` (default all three) picks the worlds; an unknown name panics.
#![allow(dead_code)]

#[path = "../src/params.rs"]
mod params;

use cartalith_engine::{WorldParams, WorldState, generate_terrain};

/// Lake cells and 4-connected lakes of a classification (class 2 is lake).
fn count(class: &[u8], gw: usize, gh: usize, wrap: bool) -> (usize, usize) {
    let n = gw * gh;
    let cells = class.iter().filter(|&&c| c == 2).count();
    let mut seen = vec![false; n];
    let mut lakes = 0;
    for s in 0..n {
        if class[s] != 2 || seen[s] {
            continue;
        }
        lakes += 1;
        let mut stack = vec![s];
        seen[s] = true;
        while let Some(i) = stack.pop() {
            let (x, y) = (i % gw, i / gw);
            let mut push = |j: usize| {
                if class[j] == 2 && !seen[j] {
                    seen[j] = true;
                    stack.push(j);
                }
            };
            if x > 0 { push(i - 1) } else if wrap { push(i + gw - 1) }
            if x + 1 < gw { push(i + 1) } else if wrap { push(i + 1 - gw) }
            if y > 0 { push(i - gw) }
            if y + 1 < gh { push(i + gw) }
        }
    }
    (cells, lakes)
}

/// The floored lake classification of one field at inflow share `share` (class 0 land, 1 ocean, 2 lake).
fn classes(ws: &WorldState, p: &WorldParams, share: f64) -> Vec<u8> {
    let (gw, gh, wrap, sea) = (p.gw, p.gh, p.world, ws.sea_level);
    let mut wb = cartalith_civ::build_water_bodies(&ws.field, gw, gh, sea, wrap, Some(&ws.rainfall));
    cartalith_civ::lake_balance::apply_lake_balance(&mut wb, &ws.field, &ws.flow_discharge, &ws.temperature, gw, gh, sea, wrap, share);
    cartalith_civ::apply_lake_area_floor(&mut wb, &ws.field, gw, gh, sea, wrap, cartalith_civ::lake_area_floor_cells(gw, gh));
    wb.classification
}

/// One frame of the classification: land in grey by height, ocean dark blue, lake cyan, and (`ghost`, the other
/// arm's lake) a lake cell the other arm held and this one does not in tan. `(x0, y0, w, h)` is the crop and `z`
/// the integer zoom (nearest neighbour). A plain classification drawing, not the app's renderer: the app's own
/// frames need a windowed session.
fn frame(path: &std::path::Path, ws: &WorldState, class: &[u8], ghost: &[u8], gw: usize, crop: (usize, usize, usize, usize), z: usize) {
    let (x0, y0, w, h) = crop;
    let (lo, hi) = ws.field.iter().fold((f32::MAX, f32::MIN), |(a, b), &v| (a.min(v), b.max(v)));
    let mut rgb = Vec::with_capacity(w * z * h * z * 3);
    for y in 0..h * z {
        for x in 0..w * z {
            let i = (y0 + y / z) * gw + x0 + x / z;
            let g = (40.0 + 180.0 * (ws.field[i] - lo) / (hi - lo)) as u8;
            let c = match (class[i], ghost[i]) {
                (1, _) => [20, 40, 90],
                (2, _) => [40, 200, 230],
                (_, 2) => [210, 170, 110],
                _ => [g, g, g],
            };
            rgb.extend_from_slice(&c);
        }
    }
    let file = std::fs::File::create(path).expect("create png");
    let mut enc = png::Encoder::new(std::io::BufWriter::new(file), (w * z) as u32, (h * z) as u32);
    enc.set_color(png::ColorType::Rgb);
    enc.set_depth(png::BitDepth::Eight);
    enc.write_header().expect("png header").write_image_data(&rgb).expect("png data");
}

/// The floored, balanced lake figure of one field at inflow share `share` (1.0 Ruling ET's whole discharge).
fn figure(ws: &WorldState, p: &WorldParams, share: f64) -> (usize, usize, usize) {
    let (gw, gh, wrap, sea) = (p.gw, p.gh, p.world, ws.sea_level);
    let mut wb = cartalith_civ::build_water_bodies(&ws.field, gw, gh, sea, wrap, Some(&ws.rainfall));
    let rep = cartalith_civ::lake_balance::apply_lake_balance(&mut wb, &ws.field, &ws.flow_discharge, &ws.temperature, gw, gh, sea, wrap, share);
    cartalith_civ::apply_lake_area_floor(&mut wb, &ws.field, gw, gh, sea, wrap, cartalith_civ::lake_area_floor_cells(gw, gh));
    let (cells, lakes) = count(&wb.classification, gw, gh, wrap);
    (cells, lakes, rep.pools)
}

fn world(name: &str) -> WorldParams {
    let mut p = params::defaults();
    match name {
        "246371" => (p.gw, p.gh, p.tect.seed, p.map_width_km, p.river_density) = (2048, 1311, 246_371, 40_075.0, 1.55),
        "483920" | "912345" => (p.gw, p.gh, p.tect.seed, p.map_width_km) = (1024, 656, name.parse().unwrap(), 40_075.0),
        other => panic!("unknown world {other}"),
    }
    p.use_gpu = std::env::var("BR_GPU").is_ok_and(|v| v == "1");
    p
}

#[test]
#[ignore = "measurement: generates six large worlds; run in release, alone"]
fn lake_area_before_and_after_the_runoff_share() {
    let pick = std::env::var("BR_WORLDS").unwrap_or_else(|_| "246371,483920,912345".into());
    for name in pick.split(',') {
        let mut before = world(name);
        before.basin_routing = false;
        let wsb = generate_terrain(&before);
        let (bc, bl, bp) = figure(&wsb, &before, 1.0);
        let mut after = world(name);
        after.basin_routing = true;
        let wsa = generate_terrain(&after);
        let (ac, al, ap) = figure(&wsa, &after, 1.0);
        if let Ok(dir) = std::env::var("LR_DIR") {
            // The frame pair (x1 and x4): Ruling ET's whole discharge on the basin-routed field against the runoff share.
            let (gw, gh) = (after.gw, after.gh);
            let (old, new) = (classes(&wsa, &after, 1.0), classes(&wsa, &after, cartalith_civ::lake_balance::RUNOFF_SHARE));
            let lost: Vec<usize> = (0..gw * gh).filter(|&i| old[i] == 2 && new[i] != 2).collect();
            let n = lost.len().max(1);
            let (cx, cy) = (lost.iter().map(|&i| i % gw).sum::<usize>() / n, lost.iter().map(|&i| i / gw).sum::<usize>() / n);
            let (cw, ch) = (gw / 4, gh / 4);
            let crop = (cx.saturating_sub(cw / 2).min(gw - cw), cy.saturating_sub(ch / 2).min(gh - ch), cw, ch);
            let dir = std::path::Path::new(&dir);
            std::fs::create_dir_all(dir).expect("frame dir");
            for (label, c, g) in [("before", &old, &new), ("after", &new, &old)] {
                frame(&dir.join(format!("{name}_{label}_x1.png")), &wsa, c, g, gw, (0, 0, gw, gh), 1);
                frame(&dir.join(format!("{name}_{label}_x4.png")), &wsa, c, g, gw, crop, 4);
            }
            println!("   frames written to {} (x4 crop {crop:?}, {} lake cells lost)", dir.display(), lost.len());
        }
        let (rc, rl, rp) = figure(&wsa, &after, cartalith_civ::lake_balance::RUNOFF_SHARE);
        println!(
            "== {name} (gpu {}): lake cells / lakes / pools | before basin routing, whole rain {bc} / {bl} / {bp} | basin routing, whole rain {ac} / {al} / {ap} | basin routing, runoff share {rc} / {rl} / {rp} | share over before {:+.1} %, whole rain over before {:+.1} %",
            before.use_gpu,
            100.0 * (rc as f64 / bc as f64 - 1.0),
            100.0 * (ac as f64 / bc as f64 - 1.0)
        );
        // Sensitivity: a flat share k of the whole discharge on the basin-routed field.
        let row: Vec<String> = [0.2f64, 0.3, 0.4, 0.5, 0.52, 0.55, 0.58, 0.6, 0.8].iter().map(|&k| {
            let (c, l, _) = figure(&wsa, &after, k);
            format!("k {k}: {c} / {l} ({:+.0} %)", 100.0 * (c as f64 / bc as f64 - 1.0))
        }).collect();
        println!("   flat share sweep: {}", row.join(" | "));
    }
}
